-- Import of the SBHS 2026 shared drive. Generated; run once with:
--   npx wrangler d1 execute highhelp-db --remote --file <this file>
UPDATE users SET last_name = '''26' WHERE id = 404 AND first_name = 'SBHS';
-- Root folders for the subjects added to src/constants.ts (the site would also create these on first visit).
INSERT OR IGNORE INTO resource_folders (name, kind, subject) VALUES ('Studies of Religion I (HSC)', 'subject', 'Studies of Religion I (HSC)');
INSERT OR IGNORE INTO resource_folders (name, kind, subject) VALUES ('English Extension 2 (HSC)', 'subject', 'English Extension 2 (HSC)');
INSERT OR IGNORE INTO resource_folders (name, kind, subject) VALUES ('Chinese Continuers (HSC)', 'subject', 'Chinese Continuers (HSC)');
INSERT OR IGNORE INTO resource_folders (name, kind, subject) VALUES ('Latin (HSC)', 'subject', 'Latin (HSC)');
INSERT OR IGNORE INTO resource_folders (name, kind, subject) VALUES ('Music Extension (HSC)', 'subject', 'Music Extension (HSC)');
WITH s(name, position) AS (VALUES ('Task 1', 1), ('Task 2', 2), ('Task 3', 3), ('Task 4', 4), ('Trial', 5), ('HSC', 6), ('Unfiled', 7)) INSERT OR IGNORE INTO resource_folders (parent_id, name, kind, position) SELECT f.id, s.name, 'section', s.position FROM resource_folders f JOIN s WHERE f.kind = 'subject' ORDER BY f.id, s.position;
CREATE TABLE _drive_import_map (k INTEGER PRIMARY KEY, folder_id INTEGER NOT NULL);
UPDATE resources SET file_key = '' WHERE file_key LIKE 'resources/1794873600000-%' AND uploader_id = 404;
DROP TABLE _drive_import_map;
